APX.be = {"country":{"name":"Belgium","tagline":"A beer country quietly rebuilding a medieval wine tradition, with Chardonnay and Crémant on Meuse slopes and Flemish hills.","classification":"Seven PDOs: in Flanders Hagelandse wijn, Haspengouwse wijn, Heuvellandse wijn and Vlaamse mousserende kwaliteitswijn; in Wallonia Côtes de Sambre et Meuse, Crémant de Wallonie and Vin mousseux de qualité de Wallonie. The cross-border Maasvallei Limburg PDO (2017) is shared with the Netherlands. PGIs are Vlaamse landwijn and Vin de pays des Jardins de Wallonie. National dates (1997 to 2009) and EU registration dates differ; the EU register lists Hagelandse and Haspengouwse wijn from 2004."},"regions":[{"name":"Wallonia","slug":"wallonia","tagline":"Chalk slopes of Hainaut and the Meuse valley, home of Crémant de Wallonie.","ids":["be-cremant-de-wallonie","be-cotes-de-sambre-et-meuse","be-vin-mousseux-de-qualite-de-wallonie"]},{"name":"Flanders","slug":"flanders","tagline":"Haspengouw's loess, Hageland's ironstone hills and the Maas valley.","ids":["be-hagelandse-wijn","be-haspengouwse-wijn","be-heuvellandse-wijn","be-maasvallei-limburg","be-vlaamse-mousserende-kwaliteitswijn"]}],"items":{"be-cotes-de-sambre-et-meuse":{"name":"Côtes de Sambre et Meuse","cat":"PDO","region":"Wallonia","created":"2004 (national); EU reg. 2006","styles":["white","red","rose"],"grapes":"Chardonnay, Pinot Noir, Auxerrois, Pinot Gris, Müller-Thurgau, Regent, Johanniter and others","summary":"Wallonia's still-wine PDO covers the valleys of the Sambre and Meuse and much of the surrounding provinces (199 municipalities in the EU register). It has the broadest grape list of any Belgian appellation, including Chasselas, Merlot, Regent, Johanniter and old Seibel hybrids, which reflects the experimental nature of Walloon viticulture.","terroir":"Slate, limestone and alluvium on Meuse and Sambre slopes.","producers":["Château de Bioul","Domaine du Chenoy","Vin de Liège","Domaine de Mellemont"],"nerd_note":"The cooperative Vin de Liège, founded in 2010, replanted the hills of the Meuse where Liège's medieval vineyards once stood.","rslug":"wallonia"},"be-cremant-de-wallonie":{"name":"Crémant de Wallonie","cat":"PDO","region":"Wallonia","created":"2008 (national); EU reg. 2009","styles":["sparkling"],"grapes":"Chardonnay, Pinot Blanc (white); Pinot Noir, Pinot Meunier","summary":"Traditional-method sparkling wine from anywhere in Wallonia, with at least nine months on lees. Chalk soils in Hainaut give Crémant of real finesse, and Domaine du Chant d'Eole and Ruffus have won international medals.","terroir":"Chalk and marl in Hainaut; slate and limestone in the Meuse valley.","producers":["Domaine du Chant d'Eole","Ruffus (Domaine des Agaises)","Château de Bioul","Domaine W"],"nerd_note":"Chant d'Eole stands among wind turbines, which gave the estate its name ('song of the wind').","rslug":"wallonia"},"be-hagelandse-wijn":{"name":"Hagelandse wijn","cat":"PDO","region":"Flanders","created":"1997 (national, first Belgian AOC); EU reg. 2004","styles":["white","red","rose","sparkling"],"grapes":"Chardonnay, Auxerrois, Pinot Gris, Müller-Thurgau, Kerner, Pinot Noir, Dornfelder and others","summary":"Hageland, east of Leuven in Flemish Brabant, was Belgium's first modern wine appellation in 1997. Its rolling hills of iron-rich sandstone (ijzerzandsteen) around Aarschot, Diest, Tienen and Hoegaarden, a region once dotted with medieval vineyards, give fresh whites and light reds. Yields are capped at 67 hl/ha.","terroir":"Ferruginous sandstone hills, sand and loam.","producers":["Wijngoed Hoenshof","Domein Kluisberg","Wijnhoeve Elzenbosch","Hof te Dieren"],"nerd_note":"The Hageland's ironstone was also the building stone of its Gothic churches.","rslug":"flanders"},"be-haspengouwse-wijn":{"name":"Haspengouwse wijn","cat":"PDO","region":"Flanders","created":"2000 (national); EU reg. 2004","styles":["white","red","rose","sparkling"],"grapes":"Chardonnay, Pinot Gris, Auxerrois, Pinot Blanc, Pinot Noir, Riesling and others","summary":"Haspengouw, the fruit-orchard country of Belgian Limburg around Sint-Truiden, Borgloon and Tongeren, has deep loess soils over chalk and is home to Belgium's best-known winery, Wijnkasteel Genoels-Elderen at Riemst, whose Chardonnay is aged in oak.","terroir":"Loess over chalk and marl; gentle slopes.","producers":["Wijnkasteel Genoels-Elderen","Clos d'Opleeuw","Wijndomein Dappersveld"],"nerd_note":"Clos d'Opleeuw near Borgloon makes a Chardonnay sometimes compared to good Burgundy.","rslug":"flanders"},"be-heuvellandse-wijn":{"name":"Heuvellandse wijn","cat":"PDO","region":"Flanders","created":"2005 (national); EU reg. 2009","styles":["white","red","sparkling"],"grapes":"Chardonnay, Pinot Gris, Pinot Noir, Johanniter, Regent and others","summary":"A small appellation in the West Flemish hills near Kemmel and Dranouter, close to the French border and the First World War battlefields of Ypres. Wijngoed Monteberg and Entre-Deux-Monts are the best-known estates.","terroir":"Clay and sand hills of the Flemish heights.","producers":["Wijngoed Monteberg","Entre-Deux-Monts"],"nerd_note":"Heuvelland's vineyards grow on ground fought over in the First World War.","rslug":"flanders"},"be-maasvallei-limburg":{"name":"Maasvallei Limburg","cat":"PDO","region":"Flanders","created":"2017 (EU reg., Belgium and the Netherlands)","styles":["white","red","rose"],"grapes":"Auxerrois, Chardonnay, Pinot Blanc, Pinot Gris, Riesling, Gewürztraminer, Siegerrebe, Pinot Noir, Dornfelder, Acolon","summary":"Maasvallei Limburg is the first cross-border PDO in the EU: 11 municipalities on both banks of the Maas, in Belgian Limburg (Maaseik, Kinrooi, Dilsen-Stokkem, Maasmechelen, Lanaken) and Dutch Limburg (Maasgouw, Echt-Susteren, Roermond, Leudal, Sittard-Geleen, Stein). Gravel and sand terraces deposited by the river give crisp whites; Wijndomein Aldeneyck at Maaseik and Wijngoed Thorn are key producers.","terroir":"Maas river gravel, sand and loam terraces; mild climate in the river valley.","producers":["Wijndomein Aldeneyck","Wijngoed Thorn","Wijngaard Steevens"],"nerd_note":"Thorn, the Dutch 'white village', gave its name to Wijngoed Thorn on the Dutch bank.","rslug":"flanders"},"be-vin-mousseux-de-qualite-de-wallonie":{"name":"Vin mousseux de qualité de Wallonie","cat":"PDO","region":"Wallonia","created":"2008 (national); EU reg. 2009","styles":["sparkling"],"grapes":"Chardonnay, Pinot Noir, Pinot Meunier, Auxerrois, Pinot Gris and others","summary":"A broader Walloon sparkling-wine PDO than Crémant, allowing more grape varieties and less strict methods, used for quality sparkling wines that fall outside the Crémant rules.","rslug":"wallonia"},"be-vlaamse-mousserende-kwaliteitswijn":{"name":"Vlaamse mousserende kwaliteitswijn","cat":"PDO","region":"Flanders","created":"2005 (national); EU reg. 2009","styles":["sparkling"],"grapes":"Chardonnay, Pinot Noir, Pinot Meunier, Pinot Blanc, Pinot Gris, Auxerrois, Riesling","summary":"The PDO for quality sparkling wine from the whole of Flanders (300 municipalities in the EU register), registered nationally in 2005. It allows the Champagne and Pinot family grapes plus Auxerrois and Riesling, and is used by most Flemish estates that make traditional-method sparkling wine.","producers":["Wijndomein Aldeneyck","Hof te Dieren"],"rslug":"flanders"}}};
